// Fonction pour obtenir toutes les pages uniques
export const getUniquePages = (): number[] => {
  const pages = [...new Set(lexiqueTerms.map(entry => entry.page))];
  return pages.sort((a, b) => a - b);
};

// Fonction pour obtenir tous les index uniques
export const getUniqueIndexes = (): number[] => {
  const indexes = [...new Set(lexiqueTerms.map(entry => entry.index))];
  return indexes.sort((a, b) => a - b);
};

// Fonction pour rechercher par page
export const searchByPage = (page: number): LexiqueTerm[] => {
  return lexiqueTerms.filter(entry => entry.page === page);
};

// Fonction pour rechercher par index
export const searchByIndex = (index: number): LexiqueTerm | undefined => {
  return lexiqueTerms.find(entry => entry.index === index);
};

// Fonction pour rechercher par mot (recherche partielle)
export const searchByMot = (searchTerm: string): LexiqueTerm[] => {
  const lowerSearch = searchTerm.toLowerCase();
  return lexiqueTerms.filter(entry => 
    entry.mot.toLowerCase().includes(lowerSearch) ||
    entry.definition.toLowerCase().includes(lowerSearch)
  );
};

// Fonction pour obtenir une entrée par son ID
export const getTermById = (id: string): LexiqueTerm | undefined => {
  return lexiqueTerms.find(entry => entry.id === id);
};

// Alias pour compatibilité
export const getLexiqueTermById = getTermById;

// Fonction pour trouver une entrée par son slug (id)
export const getTermBySlug = (slug: string): LexiqueTerm | undefined => {
  return lexiqueTerms.find(entry => entry.id === slug);
};

// Alias pour compatibilité avec les pages
export const getAvailablePages = getUniquePages;
export const getLexiqueTermsByPage = searchByPage;
export const getLexiqueTermByIndex = searchByIndex;
export const searchLexiqueTerms = searchByMot;

// Fonction pour obtenir les termes adjacents (précédent et suivant)
export const getAdjacentLexiqueTerms = (id: string): { prev: LexiqueTerm | null; next: LexiqueTerm | null } => {
  const currentIndex = lexiqueTerms.findIndex(term => term.id === id);
  if (currentIndex === -1) return { prev: null, next: null };
  
  return {
    prev: currentIndex > 0 ? lexiqueTerms[currentIndex - 1] : null,
    next: currentIndex < lexiqueTerms.length - 1 ? lexiqueTerms[currentIndex + 1] : null
  };
};
